import './MainPage.css';
import PlanInputForm from '../components/PlanInputForm';
import { Link } from 'react-router-dom';

export default function MainPage() {
  return (
    <div className="pink-background">
        <div className="background-label">
            Weather background
        </div>

        <div>
            <Link to="/result">Go to Result Page</Link>
        </div>

        <div className="plan-input-area">
            PlanInputForm 
        </div>
    </div>
  );
}
